#[path="binary.rs"]mod binary;
#[path="split.rs"]mod split;
use serde_json::{json,Value};use std::{fs,collections::BTreeSet};
type Word=[u64;4];
#[derive(Clone,Copy,Default)]struct Point{live:bool,v:u64}
#[derive(Default,Clone,PartialEq,Eq,Debug)]struct Cost{fill:u64,weighted:u64,merges:u64,projective_add:u64,projective_double:u64,tripled:u64}
impl Cost{fn generic(&self)->u64{self.fill+self.weighted+self.merges}}
fn plus(a:Point,b:Point,count:&mut u64,p:u64)->Point{*count+=u64::from(a.live&&b.live);Point{live:a.live||b.live,v:(a.v+b.v)%p}}
fn neg(a:Point,p:u64)->Point{Point{live:a.live,v:(p-a.v)%p}}
fn times(a:Point,n:u64,p:u64)->Point{Point{live:a.live,v:a.v*n%p}}
fn weighted(buckets:&[Point],cost:&mut Cost,p:u64)->Point{
 assert!(buckets.len().is_power_of_two());let mut groups=Vec::new();
 for b in buckets.chunks(256){let expected=b.iter().enumerate().map(|(i,b)|b.v*(i as u64+1)%p).sum::<u64>()%p;let mut segments=vec![b.to_vec()];while segments[0].len()>1{let correction=segments[0].iter().step_by(2).copied().collect::<Vec<_>>();for s in&mut segments{let out=s.chunks(2).map(|pair|if pair.len()==1{pair[0]}else{plus(pair[0],pair[1],&mut cost.weighted,p)}).collect();*s=out;}segments.push(correction);}let total=segments[0][0];let mut result=total;for s in segments[1..].iter().rev(){if result.live{cost.projective_double+=1;}result=times(result,2,p);result=plus(result,neg(s[0],p),&mut cost.projective_add,p);}assert_eq!(result.v,expected);groups.push((result,total));}
 let(mut sum,mut offset,mut running)=(Point::default(),Point::default(),Point::default());for(w,t)in groups.into_iter().rev(){sum=plus(sum,w,&mut cost.projective_add,p);offset=plus(offset,running,&mut cost.projective_add,p);running=plus(running,t,&mut cost.projective_add,p);}for _ in 0..8{if offset.live{cost.projective_double+=1;}offset=times(offset,2,p);}let out=plus(sum,offset,&mut cost.projective_add,p);let expected=buckets.iter().enumerate().map(|(i,b)|b.v*(i as u64+1)%p).sum::<u64>()%p;assert_eq!(out.v,expected);out
}
fn convert(w:Word,bits:usize)->Vec<(i64,i64)>{let h=bits.div_ceil(13);let mut carry=0;let mut out=Vec::new();for j in 0..h{let t=binary::extract(w,j*13,13)as i64+carry;if j+1==h{out.push((t,1));}else{let d=binary::decompose(t,13);out.push((d.sign*d.bucket,d.multiplier));carry=d.carry;}}let digits=out.iter().map(|(b,m)|b*m).collect::<Vec<_>>();let got=binary::reconstruct(&digits,13);assert_eq!(got,[w[0],w[1],w[2],w[3],0,0]);out}
fn words_mod(w:Word,p:u64)->u64{w.iter().rev().fold(0,|v,&w|((v as u128*((1u128<<64)%p as u128)+w as u128)%p as u128)as u64)}
fn admitted(w:&[Word])->bool{let n=w.len();let sample=n.min(2048);let stride=n.div_ceil(sample);let set=w.iter().step_by(stride).take(sample).collect::<BTreeSet<_>>();let observed=n.div_ceil(stride).min(sample);if set.len()*200>observed*199{return false;}let percent=if(32768..65536).contains(&n){95}else{80};let zeros=w.iter().step_by(stride).take(sample).filter(|x|**x==[0;4]).count();let nonzero=observed-zeros;if set.len()-usize::from(zeros>0)==nonzero&&nonzero*100>observed*percent{return false;}w.iter().filter(|w|**w!=[0;4]).collect::<BTreeSet<_>>().len()*100<=n*percent}
fn run(w:&[Word],ids:&[bool],g2:bool,candidate:bool,p:u64)->Cost{
 assert_eq!(w.len(),ids.len());let components=w.iter().map(|&w|if g2{let s=split::phi_split(w);vec![([s[2],s[3]&0x7fff_ffff_ffff_ffff,0,0],s[3]>>63!=0),([s[0],s[1]&0x7fff_ffff_ffff_ffff,0,0],s[1]>>63!=0)]}else{vec![(w,false)]}).collect::<Vec<_>>();let bits=if candidate{13}else{12};let windows=if g2{if candidate{10}else{11}}else if candidate{20}else{22};let parts=if g2{2}else{1};let part=w.len().div_ceil(parts);let mut cost=Cost::default();let conversions=if candidate{Some(components.iter().map(|s|s.iter().map(|(w,_)|convert(*w,if g2{126}else{254})).collect::<Vec<_>>()).collect::<Vec<_>>())}else{None};let token=|i:usize|Point{live:!ids[i],v:if ids[i]{0}else{((i as u64+1)*7919+37)%p}};let mut expected=0u64;for(i,s)in components.iter().enumerate(){for(j,(w,negative))in s.iter().enumerate(){let mut term=words_mod(*w,p)*token(i).v%p;if *negative{term=(p-term)%p;}if g2&&j==0{term=term*17%p;}expected=(expected+term)%p;}}
 if candidate{cost.tripled=conversions.as_ref().unwrap().iter().enumerate().filter(|(i,s)|!ids[*i]&&s.iter().any(|d|d[..windows-1].iter().any(|&(b,m)|b!=0&&m==3))).count()as u64;}
 let mut sums=Vec::new();for col in 0..windows{let top=col+1==windows;let capacity=if top{if g2{if candidate{1024}else{64}}else if candidate{256}else{4}}else{1usize<<(bits-1)};let mut combined=vec![Point::default();capacity];for part_i in 0..parts{let lo=part_i*part;let hi=((part_i+1)*part).min(w.len());let mut bucket=vec![Point::default();capacity];for comp in 0..if g2{2}else{1}{let mut signed_top=if top{Some(vec![Point::default();capacity*2])}else{None};if comp==1{for b in&mut bucket{*b=times(*b,17,p);}}
 for i in lo..hi{if ids[i]{continue;}let (magnitude,negative)=components[i][comp];let(d,m)=if let Some(c)=&conversions{c[i][comp][col]}else{(split::booth(&magnitude,col,bits)as i64,1)};let d=if negative{-d}else{d};if d==0{continue;}let b=d.unsigned_abs()as usize-1;assert!(b<capacity);let mut t=times(token(i),m as u64,p);if d<0{t=neg(t,p);}if let Some(s)=&mut signed_top{let index=b+if d<0{capacity}else{0};s[index]=plus(s[index],t,&mut cost.fill,p);}else{bucket[b]=plus(bucket[b],t,&mut cost.fill,p);}}
 if let Some(s)=signed_top{for i in 0..capacity{let t=plus(s[i],s[capacity+i],&mut cost.merges,p);bucket[i]=plus(bucket[i],t,&mut cost.merges,p);}}
 }
 for i in 0..capacity{combined[i]=plus(combined[i],bucket[i],&mut cost.merges,p);}}
 sums.push(weighted(&combined,&mut cost,p));}
 let mut result=Point::default();for sum in sums.into_iter().rev(){for _ in 0..bits{if result.live{cost.projective_double+=1;}result=times(result,2,p);}result=plus(result,sum,&mut cost.projective_add,p);}assert_eq!(result.v,expected);cost
}
fn read_input(file:&str,g2:bool)->(Vec<Word>,Vec<bool>){let b=fs::read(file).unwrap();let n=u64::from_le_bytes(b[8..16].try_into().unwrap())as usize;if g2{assert_eq!(&b[..8],b"B2SCAN01");assert_eq!(b.len(),16+160*n);let words=b[16+128*n..].chunks_exact(32).map(|v|std::array::from_fn(|i|u64::from_le_bytes(v[8*i..8*i+8].try_into().unwrap()))).collect();let ids=b[16..16+128*n].chunks_exact(128).map(|v|v.iter().all(|x|*x==0)).collect();(words,ids)}else{assert_eq!(&b[..8],b"ACOLUMN1");assert_eq!(b.len(),16+33*n);let words=b[16..].chunks_exact(33).map(|v|std::array::from_fn(|i|u64::from_le_bytes(v[8*i..8*i+8].try_into().unwrap()))).collect();let ids=b[16..].chunks_exact(33).map(|v|{assert!(v[32]<=1);v[32]!=0}).collect();(words,ids)}}
fn cost(c:&Cost)->Value{json!({"fill_generic_pairs":c.fill,"weighted_generic_pairs":c.weighted,"merge_generic_pairs":c.merges,"generic_pairs_excluding_formation":c.generic(),"projective_combines":c.projective_add,"projective_doublings":c.projective_double,"tripled_points":c.tripled,"formation_additions":c.tripled,"formation_doublings":c.tripled})}

fn planes(w:&[Word],ids:&[bool],g2:bool,p:u64)->Cost{
 let windows=if g2{10}else{20};let parts=if g2{2}else{1};let part=w.len().div_ceil(parts);let components=w.iter().map(|&w|if g2{let s=split::phi_split(w);vec![([s[2],s[3]&0x7fff_ffff_ffff_ffff,0,0],s[3]>>63!=0),([s[0],s[1]&0x7fff_ffff_ffff_ffff,0,0],s[1]>>63!=0)]}else{vec![(w,false)]}).collect::<Vec<_>>();let codes=components.iter().map(|row|row.iter().map(|(w,_)|convert(*w,if g2{126}else{254})).collect::<Vec<_>>()).collect::<Vec<_>>();let mut cost=Cost::default();let token=|i:usize|Point{live:!ids[i],v:if ids[i]{0}else{((i as u64+1)*7919+37)%p}};let mut expected=0;for(i,row)in components.iter().enumerate(){for(j,(w,negative))in row.iter().enumerate(){let mut term=words_mod(*w,p)*token(i).v%p;if *negative{term=(p-term)%p;}if g2&&j==0{term=term*17%p;}expected=(expected+term)%p;}}
 let mut sums=Vec::new();for col in 0..windows{let top=col+1==windows;let capacity=if top{if g2{1024}else{256}}else{4096};let mut window=Point::default();for multiplier in[1,3]{if top&&multiplier==3{continue;}let mut combined=vec![Point::default();capacity];for part_i in 0..parts{let lo=part_i*part;let hi=((part_i+1)*part).min(w.len());let mut buckets=vec![Point::default();capacity];for comp in 0..if g2{2}else{1}{if comp==1{for b in&mut buckets{*b=times(*b,17,p);}}let mut signed_top=if top{Some(vec![Point::default();2*capacity])}else{None};for i in lo..hi{if ids[i]{continue;}let (d,m)=codes[i][comp][col];if m!=multiplier||d==0{continue;}let d=if components[i][comp].1{-d}else{d};let index=d.unsigned_abs()as usize-1;assert!(index<capacity);let mut t=token(i);if d<0{t=neg(t,p);}if let Some(s)=&mut signed_top{let index=index+usize::from(d<0)*capacity;s[index]=plus(s[index],t,&mut cost.fill,p);}else{buckets[index]=plus(buckets[index],t,&mut cost.fill,p);}}if let Some(s)=signed_top{for i in 0..capacity{let t=plus(s[i],s[i+capacity],&mut cost.merges,p);buckets[i]=plus(buckets[i],t,&mut cost.merges,p);}}}for i in 0..capacity{combined[i]=plus(combined[i],buckets[i],&mut cost.merges,p);}}
 let result=weighted(&combined,&mut cost,p);let result=if multiplier==3{if result.live{cost.projective_double+=1;}plus(times(result,2,p),result,&mut cost.projective_add,p)}else{result};window=plus(window,result,&mut cost.projective_add,p);
 }sums.push(window);}
 let mut result=Point::default();for sum in sums.into_iter().rev(){for _ in 0..13{if result.live{cost.projective_double+=1;}result=times(result,2,p);}result=plus(result,sum,&mut cost.projective_add,p);}assert_eq!(result.v,expected);assert_eq!(cost.tripled,0);cost
}

#[cfg(test)]mod plane_tests{use super::*;
 #[test]fn per_plane_late_multiplier_keeps_full_dotproducts(){for g2 in[false,true]{for n in[0usize,1,7,17,1023,1025,2051]{let mut seed=0x6c6174655f6d33u64;let w=(0..n).map(|i|match i%9{0=>[0;4],1=>[1,0,0,0],2=>[5,0,0,0],_=>{let mut v=[0;4];for w in&mut v{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;*w=seed;}v[3]&=0x2fff_ffff_ffff_ffff;v}}).collect::<Vec<_>>();let ids=(0..n).map(|i|i%19==0).collect::<Vec<_>>();let a=planes(&w,&ids,g2,65537);let b=planes(&w,&ids,g2,1000000007);assert_eq!(a,b);assert_eq!(a.tripled,0);}}}
 #[test]fn empty_multiplier_planes_and_identities_do_no_generic_work(){for g2 in[false,true]{for n in[1usize,31,1025]{let w=vec![[0;4];n];let ids=vec![false;n];assert_eq!(planes(&w,&ids,g2,65537),Cost::default());let w=vec![[1,0,0,0];n];let ids=vec![true;n];assert_eq!(planes(&w,&ids,g2,65537),Cost::default());}}}
 #[test]fn signs_and_top_carries_reconstruct_after_multiplier_aggregation(){for g2 in[false,true]{let bits=if g2{126}else{254};let mut words=Vec::new();for bit in 0..bits{let mut v=[0;4];v[bit/64]=1u64<<(bit%64);words.push(v);if bit%64!=0{v[0]=v[0].wrapping_add(5);words.push(v);}}let ids=vec![false;words.len()];let a=planes(&words,&ids,g2,65537);let b=planes(&words,&ids,g2,1000000007);assert_eq!(a,b);}}
}

fn main(){let root="/home/ubuntu/src/zopro-perf-work/lfg-multiplier-planes176";let inputs:Value=serde_json::from_slice(&fs::read(format!("{root}/inputs.json")).unwrap()).unwrap();let baseline:Value=serde_json::from_slice(&fs::read("/home/ubuntu/src/zopro-perf-work/lfg-tiled-count176/analysis.json").unwrap()).unwrap();let mut results=Vec::new();let mut pass=None;for(name,input)in inputs.as_object().unwrap(){let g2=input["query"]=="B";let(w,ids)=read_input(input["file"].as_str().unwrap(),g2);if admitted(&w){results.push(json!({"case":name,"global_grouping_admitted":true,"candidate_selected":false,"reason":"preserve original global grouping"}));continue;}let a=planes(&w,&ids,g2,65537);let b=planes(&w,&ids,g2,1000000007);assert_eq!(a,b);let old=baseline["rows"].as_array().unwrap().iter().find(|r|r["case"]==name.as_str()).unwrap()["baseline"].clone();let net=old["generic_pairs_excluding_formation"].as_i64().unwrap()-a.generic()as i64;if g2{assert!(pass.is_none());pass=Some(net>0);}results.push(json!({"case":name,"global_grouping_admitted":false,"candidate_selected":g2,"G1_diagnostic_only":!g2,"baseline":old,"late_multiplier_planes":cost(&a),"net_generic_pairs_saved":net,"saving_fraction":net as f64/old["generic_pairs_excluding_formation"].as_f64().unwrap(),"input_triples":0,"two_integer_dotproduct_oracles":true,"code_payload_bytes_if_u16_20":40*w.len()}));}let a=json!({"complete":true,"primary_G2_necessary_count_screen_passed":pass.unwrap(),"width":13,"per_window_multiplier_planes":"sequential, release bucketowners retaining projective sum","rows":results,"baseline_real_counts_reused_not_rerun":true,"production_changed":false,"adopted":false,"new_latency_claim":false,"new_SDK_requests":0,"new_Gnark_exports":0,"proof_ledger":29461,"goal_achieved":false});fs::write(format!("{root}/analysis.json"),serde_json::to_vec_pretty(&a).unwrap()).unwrap();println!("LateM3 primaryG2gate{};{}",a["primary_G2_necessary_count_screen_passed"],a["rows"]);}
